package com.narada.connection

import java.util.UUID
import kotlinx.coroutines.runBlocking
import kotlinx.serialization.json.*
import org.junit.*
import org.junit.Assert.*

/** New versioned desktop-extension campaign. This does NOT rerun/relabel frozen desktop evidence. */
class AttachmentsDesktopInteropTest {
    private lateinit var f: ContentDesktopFixture
    @Before fun setup() = runBlocking<Unit> { f = ContentDesktopFixture(); f.setup() }
    @After fun close() { if (::f.isInitialized) f.close() }
    @Test fun actualDesktopDecryptsAndExportsPhoneAgeCiphertextExactly() = runBlocking<Unit> { val r = f.outgoing(); assertTrue(f.history().isEmpty()); assertTrue(f.uploaded.isEmpty()); f.sync(); assertEquals(ChatStatus.DELIVERED, f.store.document.chat!!.message(r.messageId).status); assertFalse(f.store.document.attachment(r.id).remoteStored); val done = f.attachments.run(r.id, true); assertTrue(done.remoteStored); assertEquals(listOf(0, 1, 2), f.uploaded); assertArrayEquals(f.bytes, f.export(done)); assertEquals(r.secret, done.secret) }
    @Test fun actualDesktopManifestAndAgeStreamAreAuthenticatedBeforePhoneAvailability() = runBlocking<Unit> { val r = f.incoming(); assertNull(r.receipt); assertTrue(f.fetched.isEmpty()); val done = f.attachments.run(r.id, true); assertTrue(done.available); assertFalse(done.remoteStored); assertArrayEquals(f.bytes, f.attachments.verifiedPlain(done.id)); assertEquals(sha256(f.bytes), done.receipt!!.plaintextSha256); assertTrue(f.store.document.chat!!.message(r.messageId).acknowledged) }
    @Test fun zeroLengthPlaintextStillTransfersAnAuthenticatedAgeStreamBothWays() = runBlocking<Unit> { val outgoing = f.outgoing(byteArrayOf()); f.sync(); val done = f.attachments.run(outgoing.id, true); assertTrue(done.secret!!.descriptor.size > 0); assertArrayEquals(byteArrayOf(), f.export(done)); val incoming = f.incoming("empty.bin"); f.attachments.run(incoming.id, true); assertArrayEquals(byteArrayOf(), f.attachments.verifiedPlain(incoming.id)) }
    @Test fun maximumEightMiBAndEscapedCaptionFitRealNativeAndDesktopProtocols() = runBlocking<Unit> { val bytes = TransferSamples.bytes(AttachmentRules.MAX_PLAIN); val r = f.outgoing(bytes, "\t".repeat(1024), "\"".repeat(180)); f.sync(); val done = f.attachments.run(r.id, true); assertEquals(33, done.uploaded.size); assertArrayEquals(bytes, f.export(done, "maximum.bin")) }
    @Test fun lostChunkReplyResumesSameImmutableCiphertextAfterBothRestart() = runBlocking<Unit> { val r = f.outgoing(); f.sync(); f.afterUpload = { if (it == 0) fail("PEER_TIMEOUT") }; expectFailure("PEER_TIMEOUT") { runBlocking { f.attachments.run(r.id, true) } }; assertTrue(f.store.document.attachment(r.id).uploaded.isEmpty()); assertEquals(AttachmentState.PAUSED, f.store.document.attachment(r.id).state); f.restartBoth(); assertEquals(listOf(0), f.uploaded); f.afterUpload = {}; val done = f.attachments.run(r.id, true); assertEquals(1, f.uploaded.count { it == 0 }); assertEquals(r.secret, done.secret); assertArrayEquals(f.bytes, f.export(done)) }
    @Test fun lostFinishReplyNeverClaimsAvailabilityUntilExplicitVerifiedRetry() = runBlocking<Unit> { val r = f.outgoing(); f.sync(); f.afterFinish = { fail("PEER_TIMEOUT") }; expectFailure("PEER_TIMEOUT") { runBlocking { f.attachments.run(r.id, true) } }; assertFalse(f.store.document.attachment(r.id).remoteStored); val sent = f.uploaded.toList(); f.restartBoth(); f.afterFinish = {}; val done = f.attachments.run(r.id, true); assertTrue(done.remoteStored); assertEquals(sent, f.uploaded); assertArrayEquals(f.bytes, f.export(done)) }
    @Test fun attachmentGrantWithdrawalStopsFurtherCiphertextButPreservesLocalCopy() = runBlocking<Unit> { val r = f.outgoing(); f.sync(); f.beforeUpload = { if (it == 1) { f.permissions(f.grants(attachment = false)); f.beforeUpload = {} } }; expectFailure { runBlocking { f.attachments.run(r.id, true) } }; assertFalse(f.store.document.attachment(r.id).remoteStored); assertEquals(listOf(0), f.store.document.attachment(r.id).uploaded); assertArrayEquals(f.bytes, f.attachments.verifiedPlain(r.id)); f.permissions(f.grants()); f.pairing.withActiveSession(f.peerId) { p, s -> f.pairing.health(p, s) }; assertTrue(f.attachments.run(r.id, true).remoteStored) }
    @Test fun receivedCiphertextCheckpointsSurviveBothRestartsWithoutAutoFetch() = runBlocking<Unit> { val r = f.incoming(); f.beforeBlob = { if (it == 1) fail("PEER_TIMEOUT") }; expectFailure("PEER_TIMEOUT") { runBlocking { f.attachments.run(r.id, true) } }; assertEquals(listOf(0), f.store.document.attachment(r.id).chunks); f.restartBoth(); assertNull(f.store.document.attachment(r.id).receipt); assertEquals(listOf(0), f.fetched); f.beforeBlob = {}; f.attachments.run(r.id, true); assertEquals(1, f.fetched.count { it == 0 }); assertArrayEquals(f.bytes, f.attachments.verifiedPlain(r.id)) }
    @Test fun actualServerRequiresCommittedIncomingMessageBeforeUploadBegin() = runBlocking<Unit> { val message = UUID.randomUUID().toString(); val blob = UUID.randomUUID().toString(); expectFailure("MESSAGE_UNAVAILABLE") { runBlocking { f.pairing.withActiveSession(f.peerId) { _, s -> s.post<UploadWire, UploadStatus>(AttachmentRules.PATH, UploadWire(action = buildJsonObject { put("kind", "begin"); put("message_id", message); put("blob_id", blob) })) } } }; assertTrue(f.history().isEmpty()) }
    @Test fun actualServerRejectsUnknownVersionInsteadOfFallingBack() = runBlocking<Unit> { expectFailure("PROTOCOL_INCOMPATIBLE") { runBlocking { f.pairing.withActiveSession(f.peerId) { _, s -> s.post<UploadWire, UploadCapabilities>(AttachmentRules.PATH, UploadWire(version = 2, action = buildJsonObject { put("kind", "capabilities") })) } } } }
    @Test fun actualServerRejectsManifestMismatchEvenWithValidBinaryTransportHash() = runBlocking<Unit> {
        val r = f.outgoing(); f.sync(); f.beforeUpload = { fail("PEER_TIMEOUT") }; expectFailure("PEER_TIMEOUT") { runBlocking { f.attachments.run(r.id, true) } }
        val d = r.secret!!.descriptor; val wrong = f.attachmentFiles.read(f.store.document.storeId, r.ciphertextRecord(), 0)!!.apply { this[0] = (this[0].toInt() xor 1).toByte() }
        try { f.pairing.withActiveSession(f.peerId) { _, s -> val response = Wire.decode<Envelope<UploadChunkStored>>(s.putAttachmentChunk(r.messageId, d.blob_id, 0, wrong)); assertFalse(response.ok); assertEquals("HASH_MISMATCH", response.error!!.code) } } finally { wrong.fill(0) }
        assertFalse(f.store.document.attachment(r.id).remoteStored); f.beforeUpload = {}; assertTrue(f.attachments.run(r.id, true).remoteStored)
    }
    @Test fun actualUploadIsBoundToBothCommittedMessageAndBlobIds() = runBlocking<Unit> { val r = f.outgoing(); f.sync(); expectFailure { runBlocking { f.pairing.withActiveSession(f.peerId) { _, s -> s.post<UploadWire, UploadStatus>(AttachmentRules.PATH, UploadWire(action = buildJsonObject { put("kind", "begin"); put("message_id", r.messageId); put("blob_id", UUID.randomUUID().toString()) })) } } }; assertFalse(f.store.document.attachment(r.id).remoteStored); assertTrue(f.uploaded.isEmpty()) }
}
